import { Global, Inject, Module, OnApplicationShutdown } from '@nestjs/common';
import { drizzle, NodePgDatabase } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import path from 'node:path';
import pg from 'pg';
import * as schema from './schema.js';

export const DB = 'DB';
export const PG_POOL = 'PG_POOL';
export type Db = NodePgDatabase<typeof schema>;

const MIGRATIONS_DIR = path.join(import.meta.dirname, '../../drizzle');

/** Applies pending SQL migrations from apps/server/drizzle (generated by `yarn db:generate`). */
export async function runMigrations(databaseUrl: string): Promise<void> {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 1 });
  try {
    await migrate(drizzle(pool), { migrationsFolder: MIGRATIONS_DIR });
  } finally {
    await pool.end();
  }
}

@Global()
@Module({})
export class DbModule implements OnApplicationShutdown {
  constructor(@Inject(PG_POOL) private readonly pool: pg.Pool) {}

  static forRoot(databaseUrl: string) {
    return {
      module: DbModule,
      providers: [
        { provide: PG_POOL, useFactory: () => new pg.Pool({ connectionString: databaseUrl }) },
        { provide: DB, useFactory: (pool: pg.Pool) => drizzle(pool, { schema }), inject: [PG_POOL] },
      ],
      exports: [DB],
    };
  }

  async onApplicationShutdown() {
    await this.pool.end();
  }
}
